import{_ as t,c as o,o as c,a5 as n}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"内容生命周期：发布、编辑、删除","description":"","frontmatter":{"title":"内容生命周期：发布、编辑、删除","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#3.1","branch":"main","level":1,"order":3.1},"headers":[],"relativePath":"posts/projects/zfeed/03-content-rpc-service/01-content-lifecycle-publish-edit-delete.md","filePath":"posts/projects/zfeed/03-content-rpc-service/01-content-lifecycle-publish-edit-delete.md","lastUpdated":1779632679000}'),i={name:"posts/projects/zfeed/03-content-rpc-service/01-content-lifecycle-publish-edit-delete.md"};function l(r,e,a,p,d,g){return c(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="内容生命周期-发布、编辑、删除" tabindex="-1">内容生命周期：发布、编辑、删除 <a class="header-anchor" href="#内容生命周期-发布、编辑、删除" aria-label="Permalink to &quot;内容生命周期：发布、编辑、删除&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/backfillfollowinboxlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/backfillfollowinboxlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editvideologic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editvideologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getuploadcredentialslogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getuploadcredentialslogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publish_follow_fanout.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publish_follow_fanout.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publisharticlelogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publisharticlelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publishlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publishlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publishvideologic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publishvideologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feeditembuilder_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feeditembuilder_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go</a></li></ul></details><p><code>zfeed</code> 的内容生命周期由 <code>content-rpc</code> 服务管理。它使用“基础表 + 扩展表”模式处理多态内容（文章和视频），同时为 Feed 分发与社交互动保留统一核心。</p><h2 id="数据模型-基础表与扩展表模式" tabindex="-1">数据模型：基础表与扩展表模式 <a class="header-anchor" href="#数据模型-基础表与扩展表模式" aria-label="Permalink to &quot;数据模型：基础表与扩展表模式&quot;">​</a></h2><p>所有内容实体都会在 <code>zfeed_content</code> 表中拥有一个公共记录，用于存储元数据、可见性和聚合计数。与具体内容类型相关的详细属性则存储在扩展表中。</p><table tabindex="0"><thead><tr><th>表名</th><th>实体类型</th><th>关键字段</th></tr></thead><tbody><tr><td><code>zfeed_content</code></td><td>基础元数据</td><td><code>id</code>、<code>user_id</code>、<code>content_type</code>（10：文章，20：视频）、<code>status</code>、<code>visibility</code>、<code>like_count</code></td></tr><tr><td><code>zfeed_article</code></td><td>文章扩展</td><td><code>content_id</code>（FK）、<code>title</code>、<code>cover</code>、<code>content</code>（正文）</td></tr><tr><td><code>zfeed_video</code></td><td>视频扩展</td><td><code>content_id</code>（FK）、<code>title</code>、<code>origin_url</code>、<code>cover_url</code>、<code>duration</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go#L24-L61" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go#24-61</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publisharticlelogic.go#L54-L79" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publisharticlelogic.go#54-79</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publishvideologic.go#L54-L81" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publishvideologic.go#54-81</a></p><hr><h2 id="内容发布与-fan-out" tabindex="-1">内容发布与 Fan-out <a class="header-anchor" href="#内容发布与-fan-out" aria-label="Permalink to &quot;内容发布与 Fan-out&quot;">​</a></h2><p>发布过程包含一次数据库事务，随后向基于 Redis 的 Feed 索引执行近似异步的 fan-out。</p><h3 id="实现流程" tabindex="-1">实现流程 <a class="header-anchor" href="#实现流程" aria-label="Permalink to &quot;实现流程&quot;">​</a></h3><ol><li>事务：逻辑会在一个 GORM 事务内先创建 <code>zfeed_content</code> 记录，再创建对应的扩展记录（<code>zfeed_article</code> 或 <code>zfeed_video</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publisharticlelogic.go#L50-L80" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publisharticlelogic.go#50-80</a></li><li>作者 Feed 更新：通过 Lua 脚本将内容 ID 加入作者个人发布 Feed（<code>zfeed:user:publish:{user_id}</code>），并维持最新的 $N$ 条内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publisharticlelogic.go#L93-L107" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publisharticlelogic.go#93-107</a></li><li>粉丝 Fan-out：如果内容是公开的，系统会识别作者粉丝，并把内容 ID 推入每个粉丝的个人收件箱（<code>zfeed:follow:inbox:{follower_id}</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publish_follow_fanout.go#L1-L20" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publish_follow_fanout.go#1-20</a></li></ol><h3 id="发布逻辑图" tabindex="-1">发布逻辑图 <a class="header-anchor" href="#发布逻辑图" aria-label="Permalink to &quot;发布逻辑图&quot;">​</a></h3><p>下图展示 <code>PublishArticle</code> 请求如何转换为数据库实体与缓存实体。</p><p>标题：PublishArticle 逻辑流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publisharticlelogic.go#L39-L91" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publisharticlelogic.go#39-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/publish_follow_fanout.go#L1-L20" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/publish_follow_fanout.go#1-20</a></p><hr><h2 id="内容编辑" tabindex="-1">内容编辑 <a class="header-anchor" href="#内容编辑" aria-label="Permalink to &quot;内容编辑&quot;">​</a></h2><p>编辑仅允许内容所有者执行，并支持局部更新。</p><ol><li>所有权校验：更新前，<code>ensureEditableContent</code> 会检查 <code>user_id</code> 是否与 <code>zfeed_content</code> 记录匹配，并确保内容尚未被删除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go#L79-L107" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go#79-107</a></li><li>局部更新：服务将请求字段映射为 <code>map[string]any</code>，并通过 GORM 的 <code>Updates</code> 方法执行选择性更新。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go#L35-L59" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go#35-59</a></li><li>校验：视频会校验 duration 和 URL 是否存在；文章则要求 title 和正文内容存在。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editvideologic.go#L33-L66" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editvideologic.go#33-66</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go#L30-L77" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go#30-77</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editvideologic.go#L28-L85" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editvideologic.go#28-85</a></p><hr><h2 id="软删除与索引清理" tabindex="-1">软删除与索引清理 <a class="header-anchor" href="#软删除与索引清理" aria-label="Permalink to &quot;软删除与索引清理&quot;">​</a></h2><p><code>zfeed</code> 中的删除是在数据库层执行“软删除”，同时从所有基于 Redis 的推荐索引和 Feed 索引中“硬移除”。</p><h3 id="清理级联" tabindex="-1">清理级联 <a class="header-anchor" href="#清理级联" aria-label="Permalink to &quot;清理级联&quot;">​</a></h3><p>调用 <code>DeleteContent</code> 时，系统会执行以下操作：</p><ol><li>数据库更新：在一个事务内，将 <code>zfeed_content</code> 和扩展表中的 <code>is_deleted = 1</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L41-L98" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#41-98</a></li><li>索引清理：<code>cleanupIndexes</code> 函数触发多目标移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L108-L118" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#108-118</a></li></ol><p>清理目标包括：</p><ul><li>作者 Feed：从 <code>zfeed:user:publish:{author_id}</code> 中移除。</li><li>粉丝收件箱：从所有粉丝的 <code>zfeed:follow:inbox:{follower_id}</code> 中移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L120-L142" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#120-142</a></li><li>收藏 Feed：从所有收藏过该内容的用户的 <code>zfeed:user:favorite:{user_id}</code> 中移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L148-L170" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#148-170</a></li><li>热门推荐：从全局热门 Feed ZSet 和任何活跃快照中移除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L172-L186" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#172-186</a></li></ul><h3 id="删除逻辑图" tabindex="-1">删除逻辑图 <a class="header-anchor" href="#删除逻辑图" aria-label="Permalink to &quot;删除逻辑图&quot;">​</a></h3><p>标题：DeleteContent 与清理级联</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L31-L106" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#31-106</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L108-L186" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#108-186</a></p><hr><h2 id="可见性规则" tabindex="-1">可见性规则 <a class="header-anchor" href="#可见性规则" aria-label="Permalink to &quot;可见性规则&quot;">​</a></h2><p>系统在 <code>GetContentDetail</code> 检索阶段执行可见性规则。</p><ul><li>公开：任何用户都可以访问。</li><li>私密：只有作者本人（<code>viewer_id == author_id</code>）可以获取详情。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go#L158-L196" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go#158-196</a></li><li>已删除：无论查看者是谁，都返回 <code>NotFound</code> 错误。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L59-L61" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#59-61</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go#L198-L205" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go#198-205</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/editarticlelogic.go#L97-L99" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/editarticlelogic.go#97-99</a></p>',37)])])}const f=t(i,[["render",l]]);export{h as __pageData,f as default};
